-- Table: hrm_claim
-- Source: accounting_admin_db.sql (7. HRMIS)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS hrm_claim (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    claim_number      VARCHAR(50) NOT NULL UNIQUE,
    employee_id       BIGINT NOT NULL REFERENCES masterdata_employee(id),
    claim_date        DATE NOT NULL,
    claim_type        VARCHAR(30) NOT NULL
                      CHECK (claim_type IN ('medical', 'transport', 'meal', 'other')),
    description       TEXT,
    total_amount      NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (total_amount >= 0),
    status            VARCHAR(20) NOT NULL DEFAULT 'draft'
                      CHECK (status IN ('draft', 'created', 'approved', 'rejected', 'pending', 'completed', 'reopen')),
    attachment_url    TEXT,
    notes             TEXT,
    requested_by      BIGINT REFERENCES masterdata_user(id),
    approved_by       BIGINT REFERENCES masterdata_user(id),
    approved_at       TIMESTAMPTZ,
    paid_at           TIMESTAMPTZ,
    journal_id        BIGINT REFERENCES accounting_journal(id),
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);
